css:
.rsr-root[data-theme='kendall'] { padding-top: 24px; }
.rsr-root[data-theme='kendall'] .container { width: auto; max-width: none; margin: 0; padding: 0; }
.rsr-root[data-theme='kendall'] .row::after { content: ""; display: table; clear: both; }
.rsr-root[data-theme='kendall'] .col-xs-12 { width: 100%; float: left; }
.rsr-root[data-theme='kendall'] .col-sm-7 { width: 57%; float: left; padding-right: 18px; }
.rsr-root[data-theme='kendall'] .col-sm-5 { width: 43%; float: left; }
.rsr-root[data-theme='kendall'] .col-xs-11 { width: 100%; }
.rsr-root[data-theme='kendall'] .pull-left { float: left; }
.rsr-root[data-theme='kendall'] .pull-right { float: right; }
.rsr-root[data-theme='kendall'] .text-center { text-align: center; }
.rsr-root[data-theme='kendall'] .ico::before { content: "●"; font-size: .5em; vertical-align: .45em; margin-right: .5em; opacity: .5; }
.rsr-root[data-theme='kendall'] .contact-item .icon span::before { content: "●"; font-size: .55em; opacity: .45; }
.rsr-root[data-theme='kendall'] .skills-item { margin-bottom: 10px; }
.rsr-root[data-theme='kendall'] .skills-group { font-weight: 700; }

.rsr-root[data-theme='kendall'] @charset "utf-8";
@-webkit-viewport {width: device-width; }
.rsr-root[data-theme='kendall'] @-moz-viewport {width: device-width; }
.rsr-root[data-theme='kendall'] @-ms-viewport {width: device-width; }
.rsr-root[data-theme='kendall'] @-o-viewport {width: device-width; }
.rsr-root[data-theme='kendall'] @viewport {width: device-width; }
.rsr-root[data-theme='kendall'] {font-family: 'Open Sans', Arial, Tahoma;
  font-weight: 400;
  color: #363636;
  background: #334960; }
.rsr-root[data-theme='kendall'] blockquote {font-size: 1em; }
.rsr-root[data-theme='kendall'] .container {margin-top: 80px;
  margin-bottom: 15px;
  background: #fff; }
.rsr-root[data-theme='kendall'] #photo-header {margin-top: -75px; }
.rsr-root[data-theme='kendall'] #photo {width: 160px;
  height: 160px;
  border-radius: 50%;
  overflow: hidden;
  padding: 5px;
  background: #334960;
  display: inline-block; }
.rsr-root[data-theme='kendall'] #photo img {width: 150px;
  height: 150px;
  border-radius: 50%; }
.rsr-root[data-theme='kendall'] #text-header h1 {margin: 0;
  padding: 0;
  font-size: 1.5em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: -1px; }
.rsr-root[data-theme='kendall'] #text-header h1::first-line {font-size: 1.5em;
  font-weight: 800;
  line-height: 1.5em; }
.rsr-root[data-theme='kendall'] #text-header h1 span {color: #334960;
  opacity: 0.7; }
.rsr-root[data-theme='kendall'] #text-header h1 sup {opacity: 0.5; }
.rsr-root[data-theme='kendall'] #text-header:after {width: 100%;
  height: 3px;
  border-bottom: 1px solid #ddd;
  margin-top: 15px;
  content: '';
  display: block; }
.rsr-root[data-theme='kendall'] .box {padding-bottom: 10px;
  margin-bottom: 25px; }
.rsr-root[data-theme='kendall'] .box h2 {color: #227c74;
  font-size: 1.5em;
  font-weight: 700;
  text-transform: uppercase; }
.rsr-root[data-theme='kendall'] #awards, .rsr-root[data-theme='kendall'] #education {margin-top: 20px;
  margin-bottom: 0;
  position: relative;
  padding: 1em 0;
  list-style: none; }
.rsr-root[data-theme='kendall'] #awards:before, .rsr-root[data-theme='kendall'] #education:before {width: 5px;
  height: 100%;
  position: absolute;
  left: 35px;
  top: 0;
  content: ' ';
  display: block;
  background: #32475c;
  background: -moz-linear-gradient(top,  #ffffff 0%, #32475c 7%, #32475c 89%, #ffffff 100%);
  background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#ffffff), color-stop(7%,#32475c), color-stop(89%,#32475c), color-stop(100%,#ffffff));
  background: -webkit-linear-gradient(top,  #ffffff 0%,#32475c 7%,#32475c 89%,#ffffff 100%);
  background: -o-linear-gradient(top,  #ffffff 0%,#32475c 7%,#32475c 89%,#ffffff 100%);
  background: -ms-linear-gradient(top,  #ffffff 0%,#32475c 7%,#32475c 89%,#ffffff 100%);
  background: linear-gradient(to bottom,  #ffffff 0%,#32475c 7%,#32475c 89%,#ffffff 100%);
  filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#ffffff', endColorstr='#ffffff',GradientType=0 ); }
.rsr-root[data-theme='kendall'] #awards li, .rsr-root[data-theme='kendall'] #education li {width: 100%;
  z-index: 2;
  position: relative;
  float: left; }
.rsr-root[data-theme='kendall'] #awards .year, .rsr-root[data-theme='kendall'] #education .year {width: 14%;
  background: #fff;
  padding: 10px;
  font-weight: 700;
  display: inline-block; }
.rsr-root[data-theme='kendall'] #awards .description, .rsr-root[data-theme='kendall'] #education .description {width: 83%;
  display: inline-block;
  background: #eee;
  margin-bottom: 10px;
  position: relative;
  padding: 10px;
  border-bottom: 1px solid #ccc;
  border-right: 1px solid #ccc; }
.rsr-root[data-theme='kendall'] #awards .description:after, .rsr-root[data-theme='kendall'] #education .description:after {content: '';
  position: absolute;
  top: 15px;
  right: 0;
  left: -16px;
  height: 0;
  width: 0;
  border: solid transparent;
  border-right-color: #eee;
  border-width: 8px;
  pointer-events: none; }
.rsr-root[data-theme='kendall'] #awards .description h3, .rsr-root[data-theme='kendall'] #education .description h3 {font-size: 1.2em;
  margin: 0;
  padding: 0;
  font-weight: 700; }
.rsr-root[data-theme='kendall'] #awards .description p, .rsr-root[data-theme='kendall'] #education .description p {margin-top: 5px;
  padding: 0; }
.rsr-root[data-theme='kendall'] .job {margin-bottom: 15px; }
.rsr-root[data-theme='kendall'] .job .details {margin-left: 3%;
  width: 95%;
  padding: 10px;
  margin-bottom: 10px;
  background: #eee;
  border-bottom: 1px solid #ccc;
  border-right: 1px solid #ccc; }
.rsr-root[data-theme='kendall'] .job .where {font-size: 1.2em;
  font-weight: bold; }
.rsr-root[data-theme='kendall'] .job .year {opacity: 0.7; }
.rsr-root[data-theme='kendall'] .job .profession {font-size: 1.2em;
  font-weight: bold; }
.rsr-root[data-theme='kendall'] .job .description {line-height: 1.5em; }
.rsr-root[data-theme='kendall'] .job .highlights {padding: 5px 0;
  font-weight: bold; }
.rsr-root[data-theme='kendall'] .job .job-details {padding-left: 5%;
  width: 100%; }
.rsr-root[data-theme='kendall'] .publication {margin-bottom: 0; }
.rsr-root[data-theme='kendall'] .publication .name {font-size: 1em;
  font-weight: bold; }
.rsr-root[data-theme='kendall'] .publication .year {opacity: 0.7; }
.rsr-root[data-theme='kendall'] .publication p {margin: 0;
  padding-top: 10px; }
.rsr-root[data-theme='kendall'] .contact-item {width: 100%;
  float: left; }
.rsr-root[data-theme='kendall'] .contact-item .icon {padding: 10px;
  border-right: 1px solid #ccc;
  border-bottom: 1px solid #ccc;
  color: #32475c;
  background: #eee; }
.rsr-root[data-theme='kendall'] .contact-item:last-child .icon {border-bottom: none; }
.rsr-root[data-theme='kendall'] .contact-item .title {width: 80%;
  width: calc(100% - 55px);
  font-weight: 700;
  opacity: 0.9; }
.rsr-root[data-theme='kendall'] .contact-item .title.only {margin-top: 10px; }
.rsr-root[data-theme='kendall'] .contact-item .description {width: 80%;
  width: calc(100% - 55px);
  color: #334960; }
.rsr-root[data-theme='kendall'] .item-interests, .rsr-root[data-theme='kendall'] .item-skills {height: 30px;
  color: #334960;
  padding: 5px 10px;
  margin-bottom: 5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 1.1em;
  font-weight: 600; }
.rsr-root[data-theme='kendall'] .interest, .rsr-root[data-theme='kendall'] .skill {color: #fff;
  display: inline-block;
  margin-right: 5px;
  margin-bottom: 5px;
  padding: 5px 10px;
  background: #32475c;
  position: relative;
  font-size: .85em; }
.rsr-root[data-theme='kendall'] .skill-level {background-color: #227c74;
  border-radius: 4px;
  color: #fff;
  padding: 1px 8px;
  font-size: .75em;
  position: absolute;
  margin: 1px 10px; }
.rsr-root[data-theme='kendall'] #language-skills .skill {margin: 10px 0;
  padding-bottom: 10px;
  border-bottom: 1px solid #eee; }
